// ScopeAdminServiceHandler is an implementation of the anubis.v1.ScopeAdminService service.
type ScopeAdminServiceHandler interface {
	ListScopeAxes(context.Context, *connect.Request[v1.ListScopeAxesRequest]) (*connect.Response[v1.ListScopeAxesResponse], error)
	CreateScopeAxis(context.Context, *connect.Request[v1.CreateScopeAxisRequest]) (*connect.Response[v1.CreateScopeAxisResponse], error)
	UpdateScopeAxis(context.Context, *connect.Request[v1.UpdateScopeAxisRequest]) (*connect.Response[v1.UpdateScopeAxisResponse], error)
	// Replays recent allow decisions against default_effect='deny' and reports
	// what would break. Run before flipping an axis to strict.
	StrictDryRun(context.Context, *connect.Request[v1.StrictDryRunRequest]) (*connect.Response[v1.StrictDryRunResponse], error)
	ListScopeNodeTypes(context.Context, *connect.Request[v1.ListScopeNodeTypesRequest]) (*connect.Response[v1.ListScopeNodeTypesResponse], error)
	CreateScopeNodeType(context.Context, *connect.Request[v1.CreateScopeNodeTypeRequest]) (*connect.Response[v1.CreateScopeNodeTypeResponse], error)
	ListScopeNodes(context.Context, *connect.Request[v1.ListScopeNodesRequest]) (*connect.Response[v1.ListScopeNodesResponse], error)
	// GetScopeNode fetches one node. Without it the console would have to pull
	// an entire axis to display a single selected value.
	GetScopeNode(context.Context, *connect.Request[v1.GetScopeNodeRequest]) (*connect.Response[v1.GetScopeNodeResponse], error)
	// ScopeAncestors is the chain from the axis root down, which is what makes
	// a scope decision explainable rather than a bare yes or no.
	ScopeAncestors(context.Context, *connect.Request[v1.ScopeAncestorsRequest]) (*connect.Response[v1.ScopeAncestorsResponse], error)
	CreateScopeNode(context.Context, *connect.Request[v1.CreateScopeNodeRequest]) (*connect.Response[v1.CreateScopeNodeResponse], error)
	EnsureAxisRoot(context.Context, *connect.Request[v1.EnsureAxisRootRequest]) (*connect.Response[v1.EnsureAxisRootResponse], error)
	MoveScopeNode(context.Context, *connect.Request[v1.MoveScopeNodeRequest]) (*connect.Response[v1.MoveScopeNodeResponse], error)
	ArchiveScopeNode(context.Context, *connect.Request[v1.ArchiveScopeNodeRequest]) (*connect.Response[v1.ArchiveScopeNodeResponse], error)
	// Bulk reconcile keyed on external_ref: add/rename/move/archive, manual
	// nodes untouched. dry=true computes the same report with zero writes.
	UpsertScopeNodes(context.Context, *connect.Request[v1.UpsertScopeNodesRequest]) (*connect.Response[v1.UpsertScopeNodesResponse], error)
	ListSyncSources(context.Context, *connect.Request[v1.ListSyncSourcesRequest]) (*connect.Response[v1.ListSyncSourcesResponse], error)
	CreateSyncSource(context.Context, *connect.Request[v1.CreateSyncSourceRequest]) (*connect.Response[v1.CreateSyncSourceResponse], error)
	// Rotate a feed's credentials or move it to a new endpoint without losing
	// the source's history. Config is REPLACED, never merged.
	UpdateSyncSource(context.Context, *connect.Request[v1.UpdateSyncSourceRequest]) (*connect.Response[v1.UpdateSyncSourceResponse], error)
	RunSync(context.Context, *connect.Request[v1.RunSyncRequest]) (*connect.Response[v1.RunSyncResponse], error)
}

