// TenantAdminServiceHandler is an implementation of the anubis.v1.TenantAdminService service.
type TenantAdminServiceHandler interface {
	ListTenants(context.Context, *connect.Request[v1.ListTenantsRequest]) (*connect.Response[v1.ListTenantsResponse], error)
	CreateTenant(context.Context, *connect.Request[v1.CreateTenantRequest]) (*connect.Response[v1.CreateTenantResponse], error)
	// UpdateTenant renames. The slug is not editable: it is in URLs, tokens and
	// every hosted page path, and changing it breaks links already in the world.
	UpdateTenant(context.Context, *connect.Request[v1.UpdateTenantRequest]) (*connect.Response[v1.UpdateTenantResponse], error)
	GetTenantStats(context.Context, *connect.Request[v1.GetTenantStatsRequest]) (*connect.Response[v1.GetTenantStatsResponse], error)
	// API keys are the TENANT's machine credentials (migration 0030): a
	// gateway asking authorize(), an integration reading the decision API.
	// They authenticate as the tenant's system, never as any person, and are
	// created by platform users.
	ListApiKeys(context.Context, *connect.Request[v1.ListApiKeysRequest]) (*connect.Response[v1.ListApiKeysResponse], error)
	CreateApiKey(context.Context, *connect.Request[v1.CreateApiKeyRequest]) (*connect.Response[v1.CreateApiKeyResponse], error)
	RevokeApiKey(context.Context, *connect.Request[v1.RevokeApiKeyRequest]) (*connect.Response[v1.RevokeApiKeyResponse], error)
	// SetTenantStatus suspends or retires. There is no delete — every grant,
	// identity and audit record hangs off the tenant row, and dropping it would
	// take the evidence with it. "archived" is what delete means here.
	SetTenantStatus(context.Context, *connect.Request[v1.SetTenantStatusRequest]) (*connect.Response[v1.SetTenantStatusResponse], error)
	ListRealms(context.Context, *connect.Request[v1.ListRealmsRequest]) (*connect.Response[v1.ListRealmsResponse], error)
	CreateRealm(context.Context, *connect.Request[v1.CreateRealmRequest]) (*connect.Response[v1.CreateRealmResponse], error)
	UpdateRealm(context.Context, *connect.Request[v1.UpdateRealmRequest]) (*connect.Response[v1.UpdateRealmResponse], error)
	ListRealmCategories(context.Context, *connect.Request[v1.ListRealmCategoriesRequest]) (*connect.Response[v1.ListRealmCategoriesResponse], error)
	CreateRealmCategory(context.Context, *connect.Request[v1.CreateRealmCategoryRequest]) (*connect.Response[v1.CreateRealmCategoryResponse], error)
	ListApplications(context.Context, *connect.Request[v1.ListApplicationsRequest]) (*connect.Response[v1.ListApplicationsResponse], error)
	CreateApplication(context.Context, *connect.Request[v1.CreateApplicationRequest]) (*connect.Response[v1.CreateApplicationResponse], error)
	UpdateApplication(context.Context, *connect.Request[v1.UpdateApplicationRequest]) (*connect.Response[v1.UpdateApplicationResponse], error)
	RotateClientSecret(context.Context, *connect.Request[v1.RotateClientSecretRequest]) (*connect.Response[v1.RotateClientSecretResponse], error)
	ListRoutePolicies(context.Context, *connect.Request[v1.ListRoutePoliciesRequest]) (*connect.Response[v1.ListRoutePoliciesResponse], error)
	QueryAudit(context.Context, *connect.Request[v1.QueryAuditRequest]) (*connect.Response[v1.QueryAuditResponse], error)
	// Walks the hash chain; an attacker with UPDATE rights cannot rewrite
	// history without breaking it.
	VerifyAuditChain(context.Context, *connect.Request[v1.VerifyAuditChainRequest]) (*connect.Response[v1.VerifyAuditChainResponse], error)
	ListSigningKeys(context.Context, *connect.Request[v1.ListSigningKeysRequest]) (*connect.Response[v1.ListSigningKeysResponse], error)
	// pending -> active -> retiring -> retired. Publish before signing.
	RotateSigningKey(context.Context, *connect.Request[v1.RotateSigningKeyRequest]) (*connect.Response[v1.RotateSigningKeyResponse], error)
	GetCatalogVersion(context.Context, *connect.Request[v1.GetCatalogVersionRequest]) (*connect.Response[v1.GetCatalogVersionResponse], error)
	// Deprecated: operate on the tenant's DEFAULT sign-in page. Kept so the
	// console keeps working while it moves to the multi-page API below.
	GetSigninPage(context.Context, *connect.Request[v1.GetSigninPageRequest]) (*connect.Response[v1.GetSigninPageResponse], error)
	PutSigninPage(context.Context, *connect.Request[v1.PutSigninPageRequest]) (*connect.Response[v1.PutSigninPageResponse], error)
	// --- sign-in / sign-out page builder ------------------------------------
	// A tenant may publish many of each. Every page has its own URL
	// (/p/{tenant}/{kind}/{slug}); exactly one per kind is the default that
	// /v1/authorize and /v1/logout fall back to.
	ListAuthPages(context.Context, *connect.Request[v1.ListAuthPagesRequest]) (*connect.Response[v1.ListAuthPagesResponse], error)
	GetAuthPage(context.Context, *connect.Request[v1.GetAuthPageRequest]) (*connect.Response[v1.GetAuthPageResponse], error)
	CreateAuthPage(context.Context, *connect.Request[v1.CreateAuthPageRequest]) (*connect.Response[v1.CreateAuthPageResponse], error)
	UpdateAuthPage(context.Context, *connect.Request[v1.UpdateAuthPageRequest]) (*connect.Response[v1.UpdateAuthPageResponse], error)
	DeleteAuthPage(context.Context, *connect.Request[v1.DeleteAuthPageRequest]) (*connect.Response[v1.DeleteAuthPageResponse], error)
	SetDefaultAuthPage(context.Context, *connect.Request[v1.SetDefaultAuthPageRequest]) (*connect.Response[v1.SetDefaultAuthPageResponse], error)
	// Validate a draft without saving it, so the builder shows the same errors
	// the save would produce.
	PreviewAuthPage(context.Context, *connect.Request[v1.PreviewAuthPageRequest]) (*connect.Response[v1.PreviewAuthPageResponse], error)
}

